var CLAIM_SWEEP_INTERVAL_MS = 36e5;
function startClaimSweeper({ host }) {
  let offset = Math.floor(Math.random() * 1e6);
  const run = async () => {
    let mailbox = null;
    try {
      const file = resolveMailboxPath();
      if (!existsSync4(file)) return;
      mailbox = openMailbox();
      const result = await sweepClaims(mailbox, { host, offset });
      offset = result.nextOffset;
      if (result.removed || result.receipts) getLogger().info("claims.swept", result);
    } catch (error2) {
      getLogger().warn("claims.sweep_failed", { message: error2 instanceof Error ? error2.message : String(error2) });
    } finally {
      mailbox?.close();
    }
  };
  const first = setTimeout(run, 5e3);
  first.unref?.();
  const timer = setInterval(run, CLAIM_SWEEP_INTERVAL_MS);
  timer.unref?.();
}
function startForkSweep(forks) {
  let running = false;
  const run = async () => {
    if (running) return;
    running = true;
    try {
      if (!existsSync4(forkJobsPath())) return;
      const result = await forks.sweep();
      if (result.checked) getLogger().info("forks.swept", result);
    } catch (error2) {
      getLogger().warn("forks.sweep_failed", { message: error2 instanceof Error ? error2.message : String(error2) });
    } finally {
      running = false;
    }
  };
  const first = setTimeout(run, 5e3);
  first.unref?.();
  const timer = setInterval(run, FORK_SWEEP_INTERVAL_MS);
  timer.unref?.();
  return () => {
    clearTimeout(first);
    clearInterval(timer);
    forks.close();
  };
}
